#!/usr/bin/env node
// Prebuild step — reads every vendors/*.yaml file from the
// sovereignty-vendors submodule and writes them as a plain-JS
// module at src/data/sovereignty-generated.ts.
//
// Why the extra step: sovereignty.ts is imported from vite.config.ts
// (via routeMeta.ts, for dynamic-route enumeration during SSG). Vite
// loads its own config in a plain Node context, where
// `import.meta.glob` isn't defined. Reading the YAMLs into a
// literal JS module sidesteps that: the generated file is pure
// JS/TS, works in both Node config-time and Vite bundle-time.
//
// Run automatically via the `prebuild` and `predev` npm scripts.

import { readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse } from 'yaml'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = dirname(HERE)
const VENDOR_DIR = join(ROOT, 'src', 'data', 'sovereignty-vendors', 'vendors')
const OUT = join(ROOT, 'src', 'data', 'sovereignty-generated.ts')

let files
try {
  files = readdirSync(VENDOR_DIR).filter((f) => f.endsWith('.yaml') || f.endsWith('.yml'))
} catch (err) {
  console.error(`❌ cannot read ${VENDOR_DIR}`)
  console.error(`   is the sovereignty-vendors submodule checked out?`)
  console.error(`   run: git submodule update --init --recursive`)
  console.error(err.message)
  process.exit(1)
}

if (files.length === 0) {
  console.error(`❌ no *.yaml files under ${VENDOR_DIR}`)
  process.exit(1)
}

const vendors = []
const seenSlugs = new Set()
for (const file of files.sort()) {
  const raw = readFileSync(join(VENDOR_DIR, file), 'utf8')
  const parsed = parse(raw)
  if (!parsed || typeof parsed.slug !== 'string') {
    console.error(`❌ ${file}: bad or missing slug`)
    process.exit(1)
  }
  if (seenSlugs.has(parsed.slug)) {
    console.error(`❌ duplicate slug ${JSON.stringify(parsed.slug)} at ${file}`)
    process.exit(1)
  }
  seenSlugs.add(parsed.slug)
  vendors.push(parsed)
}

const header = `// AUTO-GENERATED FILE — do not edit by hand.
//
// Generated by scripts/build-sovereignty-data.mjs from the
// vendors/*.yaml files in the sovereignty-vendors submodule. Run
// \`npm run prebuild\` or edit a YAML + \`node scripts/build-sovereignty-data.mjs\`.
//
// Committing this file to the repo means the Vite config can import
// vendor data in Node context without needing import.meta.glob
// transforms.

import type { Vendor } from './sovereignty-types'

export const rawVendors: Vendor[] = ${JSON.stringify(vendors, null, 2)}
`

mkdirSync(dirname(OUT), { recursive: true })
writeFileSync(OUT, header)
console.log(`✅ wrote ${vendors.length} vendors → ${OUT.replace(ROOT + '/', '')}`)
